// Navigate to the existing collection pages. Content, counts and publication
// routes continue to be generated by the same readings pipeline.
(()=>{
  const form=document.querySelector('.coleccion-selector');
  if(!form)return;
  const select=form.querySelector('select');
  const allowed=new Set([...select.options].map(option=>option.value));
  form.addEventListener('submit',event=>{
    event.preventDefault();
    if(allowed.has(select.value))location.assign(select.value);
  });
})();
